/**
 * Dashboard Công nợ học sinh
 * Load: ACC_CongNoHocSinh_Dashboard_Web -> StudentDebtDashboardApi.ashx -> ApexCharts
 */
(function () {
    "use strict";

    var API_URL = "/Dashboards/API/StudentDebtDashboardApi.ashx";
    var PRIMARY = "#2563eb";
    var SUCCESS = "#20c997";
    var WARNING = "#ff922b";
    var DANGER = "#fa5252";
    var INFO = "#4dabf7";
    var MUTED = "#64748b";
    var CARD_PREVIEW_LIMIT = 10;
    var CARD_CHART_MAX_HEIGHT = 360;
    var OVERVIEW_PREVIEW_LIMIT = 10;

    var chartInstances = {};
    var lastPayload = null;
    var eventsBound = false;
    var filterConfig = window.stdDashFilterConfig || {};
    var fullscreenStates = {};
    var overviewShowAll = false;

    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: "#475569",
        toolbar: { show: false },
        width: "100%"
    };

    function getEl(id) {
        return document.getElementById(id);
    }

    function formatNumber(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0";
        }
        return Math.round(num).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function formatMoney(val) {
        return formatNumber(val) + " đ";
    }

    function formatPercent(val) {
        var num = parseFloat(val);
        if (isNaN(num)) {
            return "0%";
        }
        return num.toFixed(1).replace(".", ",") + "%";
    }

    function showState(state) {
        var loading = getEl("stdDashStateLoading");
        var error = getEl("stdDashStateError");
        var empty = getEl("stdDashStateEmpty");
        var content = getEl("stdDashContent");
        if (loading) {
            loading.className = state === "loading" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (error) {
            error.className = state === "error" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (empty) {
            empty.className = state === "empty" ? "std-dash-state" : "std-dash-state d-none";
        }
        if (content) {
            content.style.display = (state === "ready" || state === "empty") ? "" : "none";
        }
    }

    function setErrorMessage(message) {
        var el = getEl("stdDashErrorMessage");
        if (el) {
            el.textContent = message || "Có lỗi xảy ra.";
        }
    }

    function postJson(payload, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", API_URL, true);
        xhr.setRequestHeader("Content-Type", "application/json; charset=utf-8");
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) {
                return;
            }
            if (xhr.status !== 200) {
                callback(false, "Không kết nối được API dashboard (HTTP " + xhr.status + ").", null);
                return;
            }
            var response = null;
            try {
                response = JSON.parse(xhr.responseText);
            } catch (e) {
                callback(false, "Phản hồi không hợp lệ từ máy chủ.", null);
                return;
            }
            if (!response || !response.success) {
                callback(false, response && response.message ? response.message : "Không tải được dữ liệu.", null);
                return;
            }
            callback(true, "", response.data);
        };
        xhr.onerror = function () {
            callback(false, "Lỗi mạng khi gọi API dashboard.", null);
        };
        xhr.send(JSON.stringify(payload));
    }

    function getSelectValue(clientId) {
        if (!clientId) {
            return "";
        }
        var el = document.getElementById(clientId);
        return el ? el.value : "";
    }

    function readFilters() {
        filterConfig = window.stdDashFilterConfig || filterConfig || {};
        return {
            scienceId: getSelectValue(filterConfig.scienceId),
            courseId: getSelectValue(filterConfig.courseId),
            classId: getSelectValue(filterConfig.classId)
        };
    }

    function destroyChart(targetId) {
        var key = targetId.replace("#", "");
        if (chartInstances[key]) {
            chartInstances[key].destroy();
            delete chartInstances[key];
        }
    }

    function renderChart(targetId, options, emptyId) {
        var key = targetId.replace("#", "");
        var el = document.querySelector(targetId);
        if (!el || typeof ApexCharts === "undefined") {
            return;
        }
        destroyChart(targetId);
        chartInstances[key] = new ApexCharts(el, options);
        chartInstances[key].render();
        if (emptyId) {
            toggleChartEmpty(targetId, emptyId, false);
        }
    }

    function toggleChartEmpty(targetId, emptyId, isEmpty) {
        var chartEl = document.querySelector(targetId);
        var emptyEl = getEl(emptyId);
        if (chartEl) {
            chartEl.style.display = isEmpty ? "none" : "";
        }
        if (emptyEl) {
            emptyEl.className = isEmpty ? "std-dash-chart-empty" : "std-dash-chart-empty d-none";
        }
    }

    function setScrollWrapHeight(scrollWrap, itemCount, rowHeight) {
        if (!scrollWrap) {
            return;
        }
        var height = Math.min(CARD_CHART_MAX_HEIGHT, Math.max(280, itemCount * rowHeight + 56));
        scrollWrap.style.maxHeight = height + "px";
    }

    function resetScrollWrap(scrollWrap) {
        if (scrollWrap) {
            scrollWrap.style.maxHeight = "";
            scrollWrap.className = "";
        }
    }

    function sliceTopData(rows, labelField, valueField, limit) {
        var pairs = [];
        var i;
        for (i = 0; i < rows.length; i++) {
            pairs.push({
                label: rows[i][labelField] || ("Mục " + (i + 1)),
                value: rows[i][valueField] || 0
            });
        }
        pairs.sort(function (a, b) {
            return (b.value || 0) - (a.value || 0);
        });
        if (limit && pairs.length > limit) {
            pairs = pairs.slice(0, limit);
        }
        var result = { labels: [], series: [], total: rows.length };
        for (i = 0; i < pairs.length; i++) {
            result.labels.push(pairs[i].label);
            result.series.push(pairs[i].value);
        }
        return result;
    }

    function setChartPreviewNote(noteId, totalCount, previewCount) {
        var noteEl = noteId ? getEl(noteId) : null;
        if (!noteEl) {
            return;
        }
        if (totalCount > previewCount) {
            noteEl.textContent = "Hiển thị top " + previewCount + " / " + formatNumber(totalCount) + " — bấm phóng to để xem đủ.";
            noteEl.className = "std-dash-chart-note";
        } else {
            noteEl.textContent = "";
            noteEl.className = "std-dash-chart-note d-none";
        }
    }

    function buildHorizontalBarOptions(labels, series, seriesName, chartHeight, isMoney, showAllLabels) {
        return {
            chart: Object.assign({}, baseChartOpts, {
                type: "bar",
                height: chartHeight
            }),
            plotOptions: {
                bar: {
                    horizontal: true,
                    borderRadius: 6,
                    barHeight: showAllLabels ? "75%" : "68%",
                    distributed: true
                }
            },
            colors: [PRIMARY, INFO, SUCCESS, WARNING, DANGER, "#9333ea", "#0891b2", "#ca8a04", "#db2777", "#059669"],
            series: [{
                name: seriesName,
                data: series
            }],
            xaxis: {
                categories: labels,
                labels: {
                    formatter: function (val) {
                        return isMoney ? formatMoney(val) : formatNumber(val);
                    }
                }
            },
            yaxis: {
                labels: {
                    maxWidth: showAllLabels ? 220 : 160
                }
            },
            dataLabels: {
                enabled: false
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return isMoney ? formatMoney(val) : formatNumber(val);
                    }
                }
            },
            legend: { show: false },
            grid: { borderColor: "#e2e8f0" }
        };
    }

    function buildStackedBarOptions(labels, planSeries, receiptSeries, remainSeries, chartHeight, showAllLabels) {
        return {
            chart: Object.assign({}, baseChartOpts, {
                type: "bar",
                height: chartHeight,
                stacked: true,
                stackType: "100%"
            }),
            plotOptions: {
                bar: {
                    horizontal: false,
                    borderRadius: 4,
                    columnWidth: showAllLabels ? "55%" : "62%"
                }
            },
            colors: [INFO, SUCCESS, DANGER],
            series: [
                { name: "Phải thu", data: planSeries },
                { name: "Đã thu", data: receiptSeries },
                { name: "Còn nợ", data: remainSeries }
            ],
            xaxis: {
                categories: labels,
                labels: {
                    rotate: showAllLabels ? -45 : -30,
                    trim: true,
                    maxHeight: 80
                }
            },
            yaxis: {
                labels: {
                    formatter: function (val) {
                        return formatMoney(val);
                    }
                }
            },
            dataLabels: { enabled: false },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatMoney(val);
                    }
                }
            },
            legend: {
                position: "top",
                horizontalAlign: "right"
            },
            grid: { borderColor: "#e2e8f0" }
        };
    }

    function buildStackedBarAbsoluteOptions(labels, planSeries, receiptSeries, remainSeries, chartHeight) {
        return {
            chart: Object.assign({}, baseChartOpts, {
                type: "bar",
                height: chartHeight,
                stacked: true
            }),
            plotOptions: {
                bar: {
                    horizontal: false,
                    borderRadius: 4,
                    columnWidth: "55%"
                }
            },
            colors: [INFO, SUCCESS, DANGER],
            series: [
                { name: "Phải thu", data: planSeries },
                { name: "Đã thu", data: receiptSeries },
                { name: "Còn nợ", data: remainSeries }
            ],
            xaxis: {
                categories: labels,
                labels: {
                    rotate: -45,
                    trim: true,
                    maxHeight: 90
                }
            },
            yaxis: {
                labels: {
                    formatter: function (val) {
                        return formatMoney(val);
                    }
                }
            },
            dataLabels: { enabled: false },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatMoney(val);
                    }
                }
            },
            legend: {
                position: "top",
                horizontalAlign: "right"
            },
            grid: { borderColor: "#e2e8f0" }
        };
    }

    function buildDonutOptions(receiptVal, remainVal) {
        return {
            chart: Object.assign({}, baseChartOpts, {
                type: "donut",
                height: 320
            }),
            labels: ["Đã thu", "Còn nợ"],
            series: [receiptVal, remainVal],
            colors: [SUCCESS, DANGER],
            plotOptions: {
                pie: {
                    donut: {
                        size: "68%",
                        labels: {
                            show: true,
                            total: {
                                show: true,
                                label: "Tổng",
                                formatter: function (w) {
                                    var total = 0;
                                    var i;
                                    for (i = 0; i < w.globals.seriesTotals.length; i++) {
                                        total += w.globals.seriesTotals[i];
                                    }
                                    return formatMoney(total);
                                }
                            }
                        }
                    }
                }
            },
            dataLabels: {
                formatter: function (val) {
                    return val.toFixed(1) + "%";
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return formatMoney(val);
                    }
                }
            },
            legend: {
                position: "bottom"
            }
        };
    }

    function registerFullscreen(key, title, optionsBuilder, layoutMode) {
        fullscreenStates[key] = {
            title: title,
            optionsBuilder: optionsBuilder,
            layoutMode: layoutMode || "horizontal"
        };
    }

    function renderDebtBarChart(config) {
        var rows = config.rows || [];
        var labelField = config.labelField;
        var valueField = config.valueField;
        var preview = sliceTopData(rows, labelField, valueField, CARD_PREVIEW_LIMIT);
        var scrollWrap = getEl(config.scrollId);
        var cardHeight = Math.min(CARD_CHART_MAX_HEIGHT, Math.max(280, preview.labels.length * 28 + 56));

        if (rows.length === 0) {
            destroyChart(config.chartId);
            toggleChartEmpty(config.chartId, config.emptyId, true);
            resetScrollWrap(scrollWrap);
            setChartPreviewNote(config.noteId, 0, CARD_PREVIEW_LIMIT);
            delete fullscreenStates[config.fsKey];
            return;
        }

        toggleChartEmpty(config.chartId, config.emptyId, false);
        setChartPreviewNote(config.noteId, rows.length, CARD_PREVIEW_LIMIT);

        if (scrollWrap) {
            scrollWrap.className = "std-dash-chart-scroll-wrap";
            setScrollWrapHeight(scrollWrap, preview.labels.length, 28);
        }

        renderChart(config.chartId, buildHorizontalBarOptions(
            preview.labels,
            preview.series,
            config.seriesName,
            cardHeight,
            true,
            false
        ), config.emptyId);

        registerFullscreen(config.fsKey, config.title, function () {
            var allLabels = [];
            var allSeries = [];
            var sorted = sliceTopData(rows, labelField, valueField, null);
            var i;
            for (i = 0; i < sorted.labels.length; i++) {
                allLabels.push(sorted.labels[i]);
                allSeries.push(sorted.series[i]);
            }
            var fsHeight = Math.max(window.innerHeight - 110, allLabels.length * 44 + 120);
            return buildHorizontalBarOptions(allLabels, allSeries, config.seriesName, fsHeight, true, true);
        }, "horizontal");
    }

    function renderKpi(data) {
        var summary = (data.summary && data.summary.length > 0) ? data.summary[0] : {};
        var kpiDebt = getEl("std-kpi-debt-students");
        var kpiPlan = getEl("std-kpi-plan");
        var kpiReceipt = getEl("std-kpi-receipt");
        var kpiRemain = getEl("std-kpi-remain");
        var kpiCollectedRate = getEl("std-kpi-collected-rate");
        var kpiRemainRate = getEl("std-kpi-remain-rate");

        if (kpiDebt) {
            kpiDebt.querySelector(".sch-dash-kpi-value").textContent = formatNumber(summary.StudentWithDebtCount);
        }
        if (kpiPlan) {
            kpiPlan.querySelector(".sch-dash-kpi-value").textContent = formatMoney(summary.TotalPlanMoney);
        }
        if (kpiReceipt) {
            kpiReceipt.querySelector(".sch-dash-kpi-value").textContent = formatMoney(summary.TotalReceiptMoney);
        }
        if (kpiRemain) {
            kpiRemain.querySelector(".sch-dash-kpi-value").textContent = formatMoney(summary.TotalRemainMoney);
        }
        if (kpiCollectedRate) {
            kpiCollectedRate.querySelector(".sch-dash-kpi-value").textContent = formatPercent(summary.CollectedRate);
        }
        if (kpiRemainRate) {
            kpiRemainRate.querySelector(".sch-dash-kpi-value").textContent = formatPercent(summary.RemainRate);
        }

        var quickTotal = getEl("stdDashQuickTotalStudents");
        var quickDebt = getEl("stdDashQuickDebtStudents");
        var quickPlan = getEl("stdDashQuickPlan");
        var quickReceipt = getEl("stdDashQuickReceipt");
        var quickRemain = getEl("stdDashQuickRemain");
        if (quickTotal) {
            quickTotal.textContent = formatNumber(summary.TotalStudentCount);
        }
        if (quickDebt) {
            quickDebt.textContent = formatNumber(summary.StudentWithDebtCount);
        }
        if (quickPlan) {
            quickPlan.textContent = formatMoney(summary.TotalPlanMoney);
        }
        if (quickReceipt) {
            quickReceipt.textContent = formatMoney(summary.TotalReceiptMoney);
        }
        if (quickRemain) {
            quickRemain.textContent = formatMoney(summary.TotalRemainMoney);
        }
    }

    function renderRatioChart(rows) {
        var row = (rows && rows.length > 0) ? rows[0] : null;
        if (!row || ((row.ReceiptMoney || 0) === 0 && (row.RemainMoney || 0) === 0)) {
            destroyChart("#stdDashChartRatio");
            toggleChartEmpty("#stdDashChartRatio", "stdDashChartRatioEmpty", true);
            delete fullscreenStates.ratio;
            return;
        }
        toggleChartEmpty("#stdDashChartRatio", "stdDashChartRatioEmpty", false);
        var receiptVal = row.ReceiptMoney || 0;
        var remainVal = row.RemainMoney || 0;
        renderChart("#stdDashChartRatio", buildDonutOptions(receiptVal, remainVal), "stdDashChartRatioEmpty");
        registerFullscreen("ratio", "Tỷ lệ đã thu / còn nợ", function () {
            return buildDonutOptions(receiptVal, remainVal);
        }, "center");
    }

    function renderTopStudentsChart(rows) {
        var mapped = [];
        var i;
        for (i = 0; i < rows.length; i++) {
            mapped.push({
                StudentLabel: (rows[i].StudentCode || "") + " - " + (rows[i].StudentLastName || "") + " " + (rows[i].StudentFirstName || ""),
                RemainMoney: rows[i].RemainMoney || 0
            });
        }
        renderDebtBarChart({
            rows: mapped,
            labelField: "StudentLabel",
            valueField: "RemainMoney",
            chartId: "#stdDashChartTopStudents",
            emptyId: "stdDashChartTopStudentsEmpty",
            scrollId: "stdDashTopStudentsScroll",
            noteId: "stdDashTopStudentsNote",
            fsKey: "topStudents",
            seriesName: "Còn nợ",
            title: "Top sinh viên nợ nhiều nhất"
        });
    }

    function renderOverviewChart(rows) {
        var limit = overviewShowAll ? null : OVERVIEW_PREVIEW_LIMIT;
        var labels = [];
        var planSeries = [];
        var receiptSeries = [];
        var remainSeries = [];
        var displayRows = rows || [];
        var scrollWrap = getEl("stdDashOverviewScroll");
        var btnViewAll = getEl("stdDashBtnViewAllOverview");
        var i;

        if (displayRows.length > OVERVIEW_PREVIEW_LIMIT && !overviewShowAll) {
            displayRows = displayRows.slice(0, OVERVIEW_PREVIEW_LIMIT);
        }

        for (i = 0; i < displayRows.length; i++) {
            labels.push(displayRows[i].ClassName || ("Lớp " + (i + 1)));
            planSeries.push(displayRows[i].PlanMoney || 0);
            receiptSeries.push(displayRows[i].ReceiptMoney || 0);
            remainSeries.push(displayRows[i].RemainMoney || 0);
        }

        if (btnViewAll) {
            if ((rows || []).length > OVERVIEW_PREVIEW_LIMIT) {
                btnViewAll.className = "btn btn-sm btn-outline-primary std-dash-btn-outline";
                btnViewAll.innerHTML = overviewShowAll
                    ? "<i class=\"bi bi-chevron-up me-1\"></i> Thu gọn"
                    : "<i class=\"bi bi-list-ul me-1\"></i> View All";
            } else {
                btnViewAll.className = "btn btn-sm btn-outline-primary std-dash-btn-outline d-none";
            }
        }

        if (labels.length === 0) {
            destroyChart("#stdDashChartOverview");
            toggleChartEmpty("#stdDashChartOverview", "stdDashChartOverviewEmpty", true);
            resetScrollWrap(scrollWrap);
            setChartPreviewNote("stdDashOverviewNote", 0, OVERVIEW_PREVIEW_LIMIT);
            delete fullscreenStates.overview;
            return;
        }

        toggleChartEmpty("#stdDashChartOverview", "stdDashChartOverviewEmpty", false);
        setChartPreviewNote("stdDashOverviewNote", (rows || []).length, OVERVIEW_PREVIEW_LIMIT);

        var chartHeight = Math.max(420, labels.length * 36 + 120);
        if (scrollWrap) {
            scrollWrap.className = "std-dash-chart-scroll-wrap";
            scrollWrap.style.maxHeight = Math.min(520, chartHeight) + "px";
        }

        renderChart("#stdDashChartOverview", buildStackedBarAbsoluteOptions(
            labels,
            planSeries,
            receiptSeries,
            remainSeries,
            chartHeight
        ), "stdDashChartOverviewEmpty");

        registerFullscreen("overview", "Phân tích tổng quan công nợ theo lớp", function () {
            var allLabels = [];
            var allPlan = [];
            var allReceipt = [];
            var allRemain = [];
            var j;
            for (j = 0; j < rows.length; j++) {
                allLabels.push(rows[j].ClassName || ("Lớp " + (j + 1)));
                allPlan.push(rows[j].PlanMoney || 0);
                allReceipt.push(rows[j].ReceiptMoney || 0);
                allRemain.push(rows[j].RemainMoney || 0);
            }
            var fsHeight = Math.max(window.innerHeight - 110, allLabels.length * 40 + 140);
            return buildStackedBarAbsoluteOptions(allLabels, allPlan, allReceipt, allRemain, fsHeight);
        }, "horizontal");
    }

    function renderAllCharts(data) {
        renderKpi(data);
        renderDebtBarChart({
            rows: data.byScience || [],
            labelField: "ScienceName",
            valueField: "RemainMoney",
            chartId: "#stdDashChartByScience",
            emptyId: "stdDashChartByScienceEmpty",
            scrollId: "stdDashByScienceScroll",
            noteId: "stdDashByScienceNote",
            fsKey: "byScience",
            seriesName: "Còn nợ",
            title: "Công nợ theo khoa"
        });
        renderDebtBarChart({
            rows: data.byCourse || [],
            labelField: "CourseName",
            valueField: "RemainMoney",
            chartId: "#stdDashChartByCourse",
            emptyId: "stdDashChartByCourseEmpty",
            scrollId: "stdDashByCourseScroll",
            noteId: "stdDashByCourseNote",
            fsKey: "byCourse",
            seriesName: "Còn nợ",
            title: "Công nợ theo khóa"
        });
        renderDebtBarChart({
            rows: data.byClass || [],
            labelField: "ClassName",
            valueField: "RemainMoney",
            chartId: "#stdDashChartByClass",
            emptyId: "stdDashChartByClassEmpty",
            scrollId: "stdDashByClassScroll",
            noteId: "stdDashByClassNote",
            fsKey: "byClass",
            seriesName: "Còn nợ",
            title: "Công nợ theo lớp"
        });
        renderTopStudentsChart(data.topStudents || []);
        renderRatioChart(data.ratio || []);
        renderOverviewChart(data.overview || []);
    }

    function hasData(data) {
        var summary = (data.summary && data.summary.length > 0) ? data.summary[0] : null;
        if (summary && (summary.TotalStudentCount || 0) > 0) {
            return true;
        }
        return false;
    }

    function loadDashboardData() {
        var filters = readFilters();
        showState("loading");
        postJson({
            action: "data",
            scienceId: filters.scienceId,
            courseId: filters.courseId,
            classId: filters.classId
        }, function (success, message, data) {
            if (!success) {
                setErrorMessage(message);
                showState("error");
                return;
            }
            lastPayload = data;
            var updateEl = getEl("stdDashUpdateTime");
            if (updateEl && data.updatedAt) {
                updateEl.textContent = data.updatedAt;
            }
            if (!hasData(data)) {
                showState("empty");
                return;
            }
            showState("ready");
            renderAllCharts(data);
        });
    }

    function openFullscreen(key) {
        var state = fullscreenStates[key];
        var overlay = getEl("stdDashFullscreenOverlay");
        var titleEl = getEl("stdDashFullscreenTitle");
        if (!state || !overlay) {
            return;
        }
        if (titleEl) {
            titleEl.textContent = state.title;
        }
        overlay.className = "std-dash-fullscreen std-dash-fullscreen-" + (state.layoutMode || "horizontal");
        renderChart("#stdDashChartFullscreen", state.optionsBuilder(), null);
    }

    function closeFullscreen() {
        var overlay = getEl("stdDashFullscreenOverlay");
        if (overlay) {
            overlay.className = "std-dash-fullscreen d-none";
        }
        destroyChart("#stdDashChartFullscreen");
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("stdDashBtnLoad");
        var btnRefresh = getEl("stdDashBtnRefresh");
        var btnCloseFs = getEl("stdDashBtnCloseFullscreen");
        var btnViewAll = getEl("stdDashBtnViewAllOverview");

        if (btnLoad) {
            btnLoad.addEventListener("click", loadDashboardData);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", function () {
                overviewShowAll = false;
                loadDashboardData();
            });
        }
        if (btnCloseFs) {
            btnCloseFs.addEventListener("click", closeFullscreen);
        }
        if (btnViewAll) {
            btnViewAll.addEventListener("click", function () {
                overviewShowAll = !overviewShowAll;
                if (lastPayload) {
                    renderOverviewChart(lastPayload.overview || []);
                }
            });
        }

        var fsMap = [
            { btnId: "stdDashBtnFsByScience", key: "byScience" },
            { btnId: "stdDashBtnFsByCourse", key: "byCourse" },
            { btnId: "stdDashBtnFsByClass", key: "byClass" },
            { btnId: "stdDashBtnFsTopStudents", key: "topStudents" },
            { btnId: "stdDashBtnFsRatio", key: "ratio" },
            { btnId: "stdDashBtnFsOverview", key: "overview" }
        ];
        var i;
        for (i = 0; i < fsMap.length; i++) {
            (function (item) {
                var btn = getEl(item.btnId);
                if (btn) {
                    btn.addEventListener("click", function () {
                        openFullscreen(item.key);
                    });
                }
            }(fsMap[i]));
        }

        document.addEventListener("keydown", function (e) {
            if (e.key === "Escape") {
                closeFullscreen();
            }
        });
    }

    function initStudentDebtDashboard() {
        bindEvents();
        loadDashboardData();
    }

    function bootStudentDebtDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentDebtDashboard);
        } else {
            initStudentDebtDashboard();
        }
    }

    bootStudentDebtDashboard();
}());
